mapper.select:
SELECT r.*, f.name as flow_name
FROM brick_flow_run r
INNER JOIN brick_flow f ON r.flow_id = f.id
WHERE f.swagger_mapping_id = #{swaggerMappingId} AND f.is_deleted = 0
AND f.name LIKE CONCAT('%', #{flowName}, '%')
AND r.status = #{status}
AND r.start_time >= #{startDate}
AND r.start_time <= #{endDate}
AND r.suite_run_id = #{testSuiteRunId}
AND r.batch_id = #{batchId}
AND r.run_type = #{runType}

    GROUP BY r.flow_id

ORDER BY r.start_time DESC
LIMIT #{offset}, #{limit}

SELECT * FROM brick_flow_run
WHERE flow_id = #{flowId}
AND status = #{status}
AND start_time >= #{startDate}
AND start_time <= #{endDate}
ORDER BY start_time DESC
LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO brick_flow_run (
    flow_id, status, triggered_by, run_type, duration_ms, error_msg,
    override_base_url, start_time, suite_run_id, batch_id, remark, create_by
) VALUES (
    #{flowId}, #{status}, #{triggeredBy}, #{runType}, #{durationMs}, #{errorMsg},
    #{overrideBaseUrl}, #{startTime}, #{suiteRunId}, #{batchId}, #{remark}, #{createBy}
)
